## 01 Weighted temporal pairs parser

```js
async function parseHypergraph(files, helpers) {
  const byName = Object.fromEntries(files.map(f => [f.name, f.text]));
  const nodesText = byName["nodes.csv"];
  const edgesText = byName["edges.csv"];
  if (!nodesText || !edgesText) throw new Error("Upload nodes.csv and edges.csv together.");

  const csv = (text) => text.trim().split(/\r?\n/).filter(Boolean).map(line => line.split(',').map(x => x.trim()));
  const nodeRows = csv(nodesText);
  const nodeHeader = nodeRows.shift();
  const idIdx = nodeHeader.indexOf('node_id');
  const labelIdx = nodeHeader.indexOf('label');
  const typeIdx = nodeHeader.indexOf('type');
  const nodeMap = new Map(nodeRows.map(r => [r[idIdx], { label: r[labelIdx], type: r[typeIdx] }]));

  const edgeRows = csv(edgesText);
  const header = edgeRows.shift();
  const idx = Object.fromEntries(header.map((h, i) => [h, i]));
  const canonicalHyperedges = edgeRows.map((r, i) => {
    const s = nodeMap.get(r[idx.source]) || { label: r[idx.source] };
    const t = nodeMap.get(r[idx.target]) || { label: r[idx.target] };
    return {
      id: `weighted_pair_${i + 1}`,
      vertices: [s.label, t.label],
      time: r[idx.timestamp],
      weight: Number(r[idx.weight]),
      attributes: { relation: r[idx.relation], sourceType: s.type, targetType: t.type }
    };
  });
  return { metadata: { source: "01-weighted-temporal-pairs" }, canonicalHyperedges };
}
```

