## 02 Event participant split parser

```js
async function parseHypergraph(files, helpers) {
  const byName = Object.fromEntries(files.map(f => [f.name, f.text]));
  const eventsText = byName["events.csv"];
  const participantsText = byName["participants.csv"];
  if (!eventsText || !participantsText) throw new Error("Upload events.csv and participants.csv together.");

  const csvObjects = (text) => {
    const lines = text.trim().split(/\r?\n/).filter(Boolean);
    const header = lines.shift().split(',').map(x => x.trim());
    return lines.map(line => Object.fromEntries(line.split(',').map((v, i) => [header[i], v.trim()])));
  };
  const severityWeight = { low: 0.5, medium: 1, high: 2, critical: 3 };
  const events = Object.fromEntries(csvObjects(eventsText).map(e => [e.event_id, e]));
  const groups = new Map();
  for (const p of csvObjects(participantsText)) {
    if (!groups.has(p.event_id)) groups.set(p.event_id, []);
    groups.get(p.event_id).push(p.participant_id);
  }
  const canonicalHyperedges = [...groups.entries()].map(([eventId, vertices]) => {
    const e = events[eventId] || {};
    return {
      id: eventId,
      vertices,
      time: e.year,
      weight: severityWeight[e.severity] || 1,
      attributes: { eventName: e.event_name, zone: e.zone, severity: e.severity }
    };
  });
  return { metadata: { source: "02-event-participant-split" }, canonicalHyperedges };
}
```

