## 03 Adjacency blocks parser

```js
async function parseHypergraph(files, helpers) {
  const byName = Object.fromEntries(files.map(f => [f.name, f.text]));
  const verticesText = byName["vertices.txt"];
  const adjacencyText = byName["adjacency.blocks"];
  if (!verticesText || !adjacencyText) throw new Error("Upload vertices.txt and adjacency.blocks together.");

  const vertexMap = new Map();
  for (const line of verticesText.split(/\r?\n/)) {
    const clean = line.trim();
    if (!clean || clean.startsWith('#')) continue;
    const [id, label, category] = clean.split('|').map(x => x.trim());
    vertexMap.set(id, { label, category });
  }

  const canonicalHyperedges = [];
  for (const line of adjacencyText.split(/\r?\n/)) {
    const clean = line.trim();
    if (!clean || clean.startsWith('#')) continue;
    const [lhs, rhsAll] = clean.split('=>').map(x => x.trim());
    const [targetsPart, ...metaParts] = rhsAll.split(';').map(x => x.trim());
    const targetIds = targetsPart.split('|').map(x => x.trim()).filter(Boolean);
    const meta = Object.fromEntries(metaParts.map(part => part.split('=').map(x => x.trim())));
    const ids = [lhs, ...targetIds];
    canonicalHyperedges.push({
      id: `adj_${canonicalHyperedges.length + 1}`,
      vertices: ids.map(id => vertexMap.get(id)?.label || id),
      time: meta.year,
      weight: 1,
      attributes: { relation: meta.relation, originalIds: ids }
    });
  }
  return { metadata: { source: "03-adjacency-blocks" }, canonicalHyperedges };
}
```

