## 04 Layered graph parser

```js
async function parseHypergraph(files, helpers) {
  const byName = Object.fromEntries(files.map(f => [f.name, f.text]));
  const layers = JSON.parse(byName["layers.json"] || "{}").layers || {};
  const csvObjects = (text) => {
    const lines = text.trim().split(/\r?\n/).filter(Boolean);
    const header = lines.shift().split(',').map(x => x.trim());
    return lines.map(line => Object.fromEntries(line.split(',').map((v, i) => [header[i], v.trim()])));
  };
  const canonicalHyperedges = [];
  for (const file of files) {
    const match = file.name.match(/^(.*)_edges\.csv$/);
    if (!match) continue;
    const layer = match[1];
    const layerInfo = layers[layer] || {};
    for (const row of csvObjects(file.text)) {
      canonicalHyperedges.push({
        id: `${layer}_${canonicalHyperedges.length + 1}`,
        vertices: [row.from, row.to],
        weight: Number(row.distance || row.quantity || 1) * Number(layerInfo.weightMultiplier || 1),
        attributes: { layer, layerDescription: layerInfo.description, ...row }
      });
    }
  }
  return { metadata: { source: "04-layered-graph" }, canonicalHyperedges };
}
```

