## 05 Update log parser

```js
async function parseHypergraph(files, helpers) {
  const byName = Object.fromEntries(files.map(f => [f.name, f.text]));
  if (!byName["initial_edges.csv"] || !byName["updates.log"]) throw new Error("Upload initial_edges.csv and updates.log.");
  const edgeMap = new Map();
  const initialLines = byName["initial_edges.csv"].trim().split(/\r?\n/).filter(Boolean);
  initialLines.shift();
  for (const line of initialLines) {
    const [edge_id, source, target, kind] = line.split(',').map(x => x.trim());
    edgeMap.set(edge_id, { edge_id, source, target, kind, time: null });
  }
  for (const line of byName["updates.log"].split(/\r?\n/)) {
    const clean = line.trim();
    if (!clean || clean.startsWith('#')) continue;
    const [op, edge_id, source, target, kind, time] = clean.split('|').map(x => x.trim());
    if (op === 'DELETE') edgeMap.delete(edge_id);
    if (op === 'ADD') edgeMap.set(edge_id, { edge_id, source, target, kind, time });
  }
  const canonicalHyperedges = [...edgeMap.values()].map(e => ({
    id: e.edge_id,
    vertices: [e.source, e.target],
    time: e.time,
    weight: 1,
    attributes: { kind: e.kind }
  }));
  return { metadata: { source: "05-update-log", updateApplied: true }, canonicalHyperedges };
}
```

