## 06 Matrix coordinate list parser

```js
async function parseHypergraph(files, helpers) {
  const byName = Object.fromEntries(files.map(f => [f.name, f.text]));
  const readMap = (text) => new Map(text.trim().split(/\r?\n/).filter(Boolean).map(line => {
    const [idx, label] = line.split(',').map(x => x.trim());
    return [Number(idx), label];
  }));
  const rowMap = readMap(byName["row_nodes.txt"]);
  const colMap = readMap(byName["col_nodes.txt"]);
  const canonicalHyperedges = [];
  for (const line of byName["edges.mtx"].split(/\r?\n/)) {
    const clean = line.trim();
    if (!clean || clean.startsWith('%')) continue;
    const parts = clean.split(/\s+/);
    if (parts.length === 3 && canonicalHyperedges.length === 0 && Number(parts[2]) > 1) continue; // matrix dimensions line
    const [r, c, w] = parts.map(Number);
    if (!Number.isFinite(r) || !Number.isFinite(c)) continue;
    canonicalHyperedges.push({
      id: `mtx_${canonicalHyperedges.length + 1}`,
      vertices: [rowMap.get(r - 1) || `row_${r}`, colMap.get(c - 1) || `col_${c}`],
      weight: Number(w || 1),
      attributes: { matrixRow: r, matrixColumn: c }
    });
  }
  return { metadata: { source: "06-matrix-coordinate-list" }, canonicalHyperedges };
}
```

