## 08 Weird delimiters parser

```js
async function parseHypergraph(files, helpers) {
  const file = files.find(f => f.name === "edge_list.weird") || files[0];
  const canonicalHyperedges = [];
  for (const line of file.text.split(/\r?\n/)) {
    const clean = line.trim();
    if (!clean || clean.startsWith('#')) continue;
    const [idPart, rest] = clean.split('::').map(x => x.trim());
    const time = (rest.match(/\[\[time=([^\]]+)\]\]/) || [])[1];
    const weight = Number((rest.match(/\[\[weight=([^\]]+)\]\]/) || [])[1] || 1);
    const verticesPart = rest.replace(/\[\[[^\]]+\]\]/g, '').trim();
    const vertices = verticesPart.split('~~').map(x => x.trim()).filter(Boolean);
    canonicalHyperedges.push({ id: idPart, vertices, time, weight, attributes: { raw: clean } });
  }
  return { metadata: { source: "08-weird-delimiters" }, canonicalHyperedges };
}
```
